pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 original, uint256 newVal) public {
        // Set the minimum sum before initialization.
        vm.prank(address(1));
        c.SetMinSum(original);
        // Freeze the contract: initialization done.
        vm.prank(address(1));
        c.Initialized();

        // A later attempt to change MinSum must revert and leave MinSum unchanged.
        vm.prank(address(2));
        bool ok;
        try c.SetMinSum(newVal) { ok = true; } catch { ok = false; }

        assertTrue(!ok && c.MinSum() == original);
    }
}

