pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 newVal, address actor) public {
        // seed MinSum with a first (successful) call from the fuzzed actor/value space
        vm.assume(actor != address(0));
        uint256 before = c.MinSum();
        vm.prank(actor);
        c.SetMinSum(newVal);
        before = c.MinSum();
        // freeze configuration: subsequent SetMinSum calls revert
        vm.prank(actor);
        c.Initialized();
        // a now-reverting SetMinSum must not change MinSum
        bool ok;
        vm.prank(actor);
        try c.SetMinSum(newVal) { ok = true; } catch { ok = false; }
        assertTrue(ok ? (c.MinSum() == newVal) : (c.MinSum() == before));
    }
}

