pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 pre, uint256 v, address caller) public {
        // wide admissible domain: any pre-state value, any requested value, any caller
        vm.assume(caller != address(0));

        // establish the pre-state MinSum = pre via a successful SetMinSum (contract not yet initialized)
        vm.prank(caller);
        c.SetMinSum(pre);

        // freeze the contract: any subsequent SetMinSum must revert without effect
        vm.prank(caller);
        c.Initialized();

        uint256 before = c.MinSum();
        bool ok;
        vm.prank(caller);
        try c.SetMinSum(v) { ok = true; } catch { ok = false; }

        // GENERAL RULE: a SetMinSum(v) call either succeeds with MinSum()==v,
        // or reverts with MinSum() left exactly as before the call.
        assertTrue(ok ? (c.MinSum() == v) : (c.MinSum() == before));
    }
}

