pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 committed, uint256 attackerVal, address actor) public {
        // 1. keep the fuzzed domain wide: any two values and any actor
        // 2. scenario setup:
        //    - actor commits `committed` as MinSum before initialization (this call succeeds in both P and M)
        vm.prank(actor);
        c.SetMinSum(committed);
        assertEq(c.MinSum(), committed); // note: setup sanity, not the deciding assertion

        //    - initialize the vault: after this, every SetMinSum must revert
        c.Initialized();

        //    - a later actor tries to sneak in a new MinSum value; the call must revert
        vm.prank(actor);
        bool ok;
        try c.SetMinSum(attackerVal) { ok = true; } catch { ok = false; }

        // 3. deciding assertion (universal rule):
        //    a reverted SetMinSum must never change MinSum. The mutant assigns
        //    MinSum = _val BEFORE the initialized-check, so after the revert
        //    c.MinSum() == attackerVal while the reference keeps `committed`.
        assertTrue(
            ok
                ? c.MinSum() == attackerVal
                : c.MinSum() == committed
        );
    }
}

