pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";
import {LogFile} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 lockTime, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1 wei, 1 ether);
        lockTime = bound(lockTime, 0, 365 days);
        LogFile logFile = new LogFile();
        vm.startPrank(actor);
        c.SetLogFile(address(logFile));
        vm.deal(actor, amount);
        c.Put{value: amount}(lockTime);
        vm.stopPrank();
        (address sender, , uint256 val, ) = logFile.History(0);
        assertTrue(sender == actor && val == amount, "Put must log a message to the configured LogFile for every caller/amount");
    }
}

